draw((0,5)--(0,10),dashed+black+linewidth(1));
draw((0,5)--(10,0),dashed+black+linewidth(1));
draw((10,0)--(20,5),dashed+black+linewidth(1));
draw((10,5)--(20,10),dashed+black+linewidth(1));
draw((10,5)--(10,0),dashed+black+linewidth(1));
label("5",(0,0)--(0,5),W);
label("5",(0,0)--(5,0),S);
label("5",(0,5)--(5,10),NW);
label("$h$",(10,5)--(10,0),S);
